INSERT INTO `yeu_cau_dao_tao_lai` VALUES (3,3,NULL,1,6,'Đánh giá chưa đạt (điểm tổng 81.1; dưới 70: Phục vụ 69).','DaDuyet','ChuaCoKetQua','2026-10-13 02:47:12','2026-10-13 02:47:12','2026-10-13 02:47:12','2026-10-13 02:47:12',44,'Trưởng ca đề xuất','{\"source\": \"Trưởng ca đề xuất\", \"status\": \"ChoPheDuyet\", \"details\": {\"danhgialai\": {\"criteria\": [\"phuc_vu\"], \"assessor_id\": \"1\", \"assessment_date\": \"2026-10-26\"}, \"hoclaibaihoc\": {\"course_id\": \"5\", \"lesson_ids\": [\"9\"]}}, \"proposed_by\": 1}',NULL,NULL,NULL,'ChoGiao',NULL,NULL),(10,20,NULL,1,6,'Đánh giá chưa đạt (điểm tổng 77.6; dưới 70: Kỹ năng 66). Kỹ năng đánh sữa microfoam chưa ổn định, latte art chưa đạt chuẩn; cần học lại và thực hành có kèm cặp.','DaDuyet','ChuaCoKetQua','2026-08-23 08:00:00','2026-08-23 08:00:00','2026-08-23 08:00:00','2026-10-27 14:24:00',85,'Trưởng ca đề xuất','{\"source\": \"Trưởng ca đề xuất\", \"status\": \"ChoPheDuyet\", \"details\": {\"danhgialai\": {\"criteria\": [\"ky_nang\"], \"assessor_id\": \"1\", \"assessment_date\": \"2026-10-27\"}, \"daotaobosung\": {\"skill\": \"Đánh sữa microfoam giờ cao điểm\", \"owner_id\": \"1\", \"instructions\": \"Kèm cặp 3 ca cao điểm, kiểm tra độ mịn sữa từng ly\"}, \"hoclaibaihoc\": {\"course_id\": \"3\", \"lesson_ids\": [\"6\"]}}, \"proposed_by\": 1}',1,'2026-11-02','2026-11-05','DangThucHien','Học lại bài học liên quan\nKhóa: Kỹ Thuật Espresso & Đánh Sữa Nâng Cao\nKỹ thuật Đánh sữa Microfoam & Latte Art\nĐào tạo bổ sung: kèm cặp 3 ca cao điểm, kiểm tra độ mịn sữa từng ly',NULL),(11,27,NULL,1,6,'Đánh giá chưa đạt (điểm tổng 72.9; dưới 70: Kỹ năng 62). Kiến thức lý thuyết tốt nhưng thao tác chiết xuất chưa đạt định lượng, sữa đánh còn bọt lớn.','DaDuyet','ChuaDat','2026-08-20 03:00:00','2026-08-20 04:00:00','2026-08-20 03:00:00','2026-10-30 07:22:37',95,'Trưởng ca đề xuất','{\"source\": \"Trưởng ca đề xuất\", \"details\": {\"theodoica\": {\"behavior\": \"Kèm cặp thao tác chiết xuất espresso và đánh sữa microfoam theo định lượng chuẩn.\", \"shift_count\": 5}}}',1,'2026-10-06','2026-10-08','DungDaoTao',NULL,98);
